import re
import datetime

from ta_moler.events.rtg.genericrtg_lineevent import GenericRtgLineEvent


class SectorsInoperational(GenericRtgLineEvent):
    """Sectors inoperational event class."""

    re_error = re.compile(r'Executor: ERROR: All configured sectors are inoperational. Stopping test')
    re_error_sectors_and_apps = re.compile(
        r'Connection Manager: All SECTOR / Apps connections lost - disconnecting'
    )

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """Event for sectors inoperational.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(SectorsInoperational, self).__init__(connection=connection, runner=runner,
                                                   till_occurs_times=till_occurs_times,
                                                   detect_patterns=[self.re_error, self.re_error_sectors_and_apps],
                                                   match='any')


